#!/bin/bash
#SBATCH --job-name=kraken_pipe
#SBATCH --cpus-per-task=16
#SBATCH --mem=400G
#SBATCH --time=12:00:00
#SBATCH -p smp

module load Python/3.12.3-GCCcore-13.3.0
module load Biopython/1.83-foss-2023a

# 1. Set ID from command line argument
ID=$1
KMER=${2:-1000}
READS=${3:-10}

# 2. Define PATHS
CHM13_DB="/scratch/pioneer/users/dxn150/krakenuniq_CHM13"
STD_DB="/scratch/pioneer/users/dxn150/krakenuniq_standard"
KT_EXTRACT="/home/txl80/KrakenTools-1.2.1/extract_kraken_reads.py"

# 3. Define FASTQ source and Output Destination
BASE_DIR=$(pwd)
R1="$BASE_DIR/${ID}_R1.fastq"
R2="$BASE_DIR/${ID}_R2.fastq"

THREADS=16

# 4. Create output directory and move into it
OUTPUT_DIR="$BASE_DIR/$ID"
mkdir -p "$OUTPUT_DIR"
chmod 770 "$OUTPUT_DIR"
cd "$OUTPUT_DIR" || exit

echo "Starting workflow for Sample: $ID, Unique Kmer value: $KMER, Reads value: $READS"

###############################################################################
