n.fastq" -o "${ID}_R1_non_human_non_contam.fasta" -o2 "${ID}_R2_non_human_non_contam.fasta"

krakenuniq --db "$STD_DB" --threads $THREADS --paired \
    --output "${ID}_pe_non_human_non_contam_std.out" \
    --report "${ID}_pe_non_human_non_contam_std.report" \
    "${ID}_R1_non_human_non_contam.fasta" "${ID}_R2_non_human_non_contam.fasta"

###############################################################################
# PART 3: Post-Processing and Reporting
###############################################################################
echo "--- Parsing Final KrakenUniq Reports ($ID) ---"

FINAL_REPORT="${ID}_pe_non_human_non_contam_std.report"

# A. Generate report without header lines
awk '!/^#/ && !/^%/' "$FINAL_REPORT" > "${ID}_no_headers.report"

# B. Extract full virus taxonomic lineage report with domain safeguard trap
awk '$7 == 10239 {p=1} p; p && $8 == "superkingdom" && $7 != 10239 {exit}' "$FINAL_REPORT" > "${ID}_virus_report.txt"

# C. Filter genus level for kmers ($4) >= 1000 and total reads ($2) >= 10, then output transposed structure
awk '!/^#/ && $8 == "genus" && $4 >= $KMER && $2 >= $READS { match($0, /([^\t ]+[\t ]*){8}/); name = substr($0, RLENGTH+1); names = (names ? names "\t" : "") name; reads = (reads ? reads "\t" : "") $4} END {print names; print reads}' "$FINAL_REPORT" > "${ID}_filtered_genus_transposed.txt"

# D. Filter species level for kmers >= 1000 and total reads >= 10
awk '!/^#/ && $8 == "species" && $4 >= $KMER && $2 >= $READS { match($0, /([^\t ]+[\t ]*){8}/); name = substr($0, RLENGTH+1); names = (names ? names "\t" : "") name; reads = (reads ? reads "\t" : "") $4} END {print names; print reads}' "$FINAL_REPORT" > "${ID}_filtered_genus_transposed.txt"

echo "Workflow complete for Sample: $ID"
 
